import {type ChartType} from 'chart.js';

export type BootstrapColorVar =
  | '--bs-primary'
  | '--bs-secondary'
  | '--bs-success'
  | '--bs-danger'
  | '--bs-warning'
  | '--bs-info'
  | '--bs-light'
  | '--bs-dark';

/**
 * Reads a Bootstrap CSS variable and returns its trimmed value.
 */
function readVar(name: string): string {
  return getComputedStyle(document.documentElement)
    .getPropertyValue(name)
    .trim();
}

/**
 * Given a list of `--bs-*` variable names, returns an array of resolved
 * colour strings (e.g. `"#002f2a"`).  If the variable has an `-rgb`
 * counterpart the helper also produces an `rgba()` string that can be
 * used for chart fills with transparency.
 */
export function resolveBootstrapColors(
  vars: BootstrapColorVar[],
): {solid: string; alpha: (a: number) => string}[] {
  return vars.map((v) => {
    const solid = readVar(v);
    const rgb = readVar(`${v}-rgb`);
    return {
      solid,
      alpha: (a: number) =>
        rgb ? `rgba(${rgb}, ${a})` : solid,
    };
  });
}

/**
 * Maps each Solicitud status enum value to the Bootstrap CSS variable
 * that represents its colour in the current theme.
 */
export const statusColorMap: Record<string, BootstrapColorVar> = {
  Autorizada: '--bs-success',
  'No Autorizada': '--bs-danger',
  'En Dictaminación': '--bs-info',
  Subsanada: '--bs-warning',
  Enviada: '--bs-primary',
  Incompleta: '--bs-secondary',
  'No Presentada': '--bs-secondary',
  Suspendida: '--bs-secondary',
  Revocada: '--bs-secondary',
};

/**
 * Given a list of Solicitud status strings, resolves their
 * Bootstrap colours and returns `Chart.js`-ready `backgroundColor`
 * and `borderColor` arrays.
 */
export function resolveStatusColors(
  statuses: string[],
  type: ChartType = 'doughnut',
): {backgroundColor: string[]; borderColor: string[]; hoverBackgroundColor: string[]} {
  const vars = statuses.map(
    (s) => (statusColorMap[s] ?? '--bs-secondary') as BootstrapColorVar,
  );
  const resolved = resolveBootstrapColors(vars);
  const solidColors = resolved.map((c) => c.solid);

  return {
    backgroundColor:
      type === 'line' || type === 'bar'
        ? resolved.map((c) => c.alpha(0.6))
        : solidColors,
    borderColor: solidColors,
    hoverBackgroundColor:
      type === 'line' || type === 'bar'
        ? resolved.map((c) => c.alpha(0.8))
        : resolved.map((c) => c.alpha(0.8)),
  };
}
