import {
  Component,
  DestroyRef,
  ElementRef,
  afterNextRender,
  effect,
  inject,
  input,
  viewChild,
} from '@angular/core';
import {ThemeService} from '../../../services/theme.service';
import {Chart, registerables, type ChartData, type ChartOptions, type ChartType} from 'chart.js';

Chart.register(...registerables);

interface DatasetWithColorVars {
  __colorVars?: string[];
  backgroundColor?: string | string[];
  borderColor?: string | string[];
}

@Component({
  selector: 'app-vdin-chart',
  template: `<canvas #canvas></canvas>`,
})
export class VdinChartComponent {
  readonly type = input.required<ChartType>();
  readonly data = input.required<ChartData>();
  readonly options = input<ChartOptions>();

  private readonly canvasRef = viewChild<ElementRef<HTMLCanvasElement>>('canvas');
  private readonly themeService = inject(ThemeService);
  private readonly destroyRef = inject(DestroyRef);

  private chart: Chart | null = null;

  constructor() {
    afterNextRender(() => {
      this.createChart();
    });

    effect(() => {
      const type = this.type();
      this.data();
      this.options();
      if (!this.chart) return;

      if ((this.chart.config as {type?: ChartType}).type !== type) {
        this.chart.destroy();
        this.createChart();
        return;
      }

      this.chart.data = this.data();
      this.chart.options = this.options() ?? {};
      this.applyThemeColors();
      this.chart.update();
    });

    effect(() => {
      this.themeService.isDark();
      if (!this.chart) return;
      this.applyThemeColors();
      this.chart.update();
    });
  }

  private createChart(): void {
    const canvas = this.canvasRef()?.nativeElement;
    if (!canvas) return;

    this.chart = new Chart(canvas, {
      type: this.type(),
      data: this.data(),
      options: this.options() ?? {},
    });

    this.applyThemeColors();
    this.chart.update();
  }

  private applyThemeColors(): void {
    if (!this.chart) return;

    const datasets = this.chart.data.datasets;
    const isLine = this.type() === 'line' || this.type() === 'bar';

    datasets.forEach((ds) => {
      const dsWithVars = ds as DatasetWithColorVars;
      const colorVars = dsWithVars.__colorVars;

      if (colorVars?.length) {
        const resolved = colorVars.map((v) => {
          const solid = getComputedStyle(document.documentElement)
            .getPropertyValue(v)
            .trim();
          const rgb = getComputedStyle(document.documentElement)
            .getPropertyValue(`${v}-rgb`)
            .trim();
          return {solid, alpha: (a: number) => (rgb ? `rgba(${rgb}, ${a})` : solid)};
        });

        if (isLine) {
          dsWithVars.backgroundColor = resolved.map((c) => c.alpha(0.6));
          dsWithVars.borderColor = resolved.map((c) => c.solid);
        } else {
          dsWithVars.backgroundColor = resolved.map((c) => c.solid);
          dsWithVars.borderColor = resolved.map((c) => c.solid);
        }
      }
    });
  }
}
